begin
              Clear;
              if y = 96 then
              if wantexit then begin
                 with party do begin
                    xaxis := 82; yaxis := 17; map := 4;
                 end;
                 load; scroll(TRUE);
              end
              else begin
                 dec(y); scroll(TRUE);
              end;
              if y = 88 then begin
                 if map[x,y] = 0 then y := 80
                 else begin
                    with party do begin
                       xaxis := 82; yaxis := 17; map := 4;
                    end;
                    load; scroll(TRUE);
                    exit;
                 end;
              end;
              if y = 71 then begin
                 if map[x,y] = 0 then y := 63
                 else begin
                    with party do begin
                       xaxis := 82; yaxis := 17; map := 4;
                    end;
                    load; scroll(TRUE);
                    exit;
                 end;
              end;
              if y = 91 then begin
                 Print(15,' 다음 물음이 맞다면 왼쪽길로, 아니면 오른쪽');
                 Print(15,'길로 가시오.');
                 Print(7,'');
                 i := random(8);
                 case i of
                    0 : Print(7,'문> CONFIG.SYS가 없으면 부팅이 안된다');
                    1 : Print(7,'문> Quick-BASIC은 인터프리터어 이다');
                    2 : Print(7,'문> Super VGA는 호환이 잘된다');
                    3 : Print(7,'문> 8-bit APPLE의 CPU는 Z - 80 이다');
                    4 : Print(7,'문> COMMAND.COM 안에 도스 명령이 들어있다');
                    5 : Print(7,'문> AdLib 카드는 9 채널이다');
                    6 : Print(7,'문> Ultima의 제작자는 리차드 게리오트이다');
                    7 : Print(7,'문> 당신의 컴퓨터는 IBM 계열이다');
                 end;
                 for j := 23 to 26 do map[j,y] := 44;
                 if i < 4 then begin
                    map[8,88] := 52; map[43,88] := 0;
                 end
                 else begin
                    map[8,88] := 0; map[43,88] := 52;
                 end;
                 delay(3000);
                 PressAnyKey;
              end;
              if y = 75 then begin
                 Print(15,' 다음 물음이 맞다면 왼쪽길로, 아니면 오른쪽');
                 Print(15,'길로 가시오.');
                 Print(7,'');
                 i := random(8);
                 case i of
                    0 : Print(7,'문> 태양계의 제 4 혹성은 지구이다');
                    1 : Print(7,'문> 북극성이 가장 밝은 별이다');
                    2 : Print(7,'문> 1월의 수호성좌는 1월에 볼수있다');
                    3 : Print(7,'문> 빛보다 빠른 입자는 실험상 없었다');
                    4 : Print(7,'문> 달이 지구보다 먼저 생겨났다');
                    5 : Print(7,'문> 시그너스 X1은 블랙홀이다');
                    6 : Print(7,'문> 과거로의 타임머신은 불가능하다');
                    7 : Print(7,'문> 북극성은 주기적으로 달라진다');
                 end;
                 for j := 23 to 26 do map[j,y] := 44;
                 if i < 4 then begin
                    map[8,71] := 52; map[43,71] := 0;
                 end
                 else begin
                    map[8,71] := 0; map[43,71] := 52;
                 end;
                 delay(3000);
                 PressAnyKey;
              end;
              if y = 54 then begin
                 Print(15,'<< 다음의 옳고 그름을 가리시오 >>');
                 Print(7,'');
                 i := random(8);
                 case i of
                    0 : Print(7,'문> 이 게임의 배경은 4개의 대륙이다');
                    1 : Print(7,'문> Ancient Evil은 응징되어야 한다');
                    2 : Print(7,'문> Lord Ahn만이 유일한 Semi-God이다');
                    3 : Print(7,'문> 이 세계의 모든 악은 응징되어야 한다');
                    4 : Print(7,'문> 이 게임의 제작자는 안 영기이다');
                    5 : Print(7,'문> 게임속의 인물은 거의 별의 이름을 가졌다');
                    6 : Print(7,'문> Necromancer는 신의 경지에 이르렀다');
                    7 : Print(7,'문> Necromancer는 이 세계의 존재가 아니었다');
                 end;
                 m[0] := '';
                 m[1] := '위의 말은 옳다';
                 m[2] := '위의 말은 잘못되었다';
                 k := select(120,2,2,FALSE,TRUE);
                 if k = 0 then begin
                    inc(y);
                    scroll(TRUE);
                    exit;
                 end;
                 for j := 23 to 25 do map[j,y] := 44;
                 if ((k=1) and (i>3)) or ((k=2) and (i<4)) then begin
                    for j := 49 to 52 do begin
                       map[22,j] := 25;
                       map[26,j] := 23;
                       for i := 23 to 25 do map[i,j] := 44;
                    end;
                 end
                 else begin
                    with party do begin
                       xaxis := 82; yaxis := 17; map := 4;
                    end;
                    load; scroll(TRUE);
                    exit;
                 end;
                 scroll(TRUE);
              end;
              if (x in [8..42]) and (y in [19..43]) then begin
                 if party.etc[1] > 0 then dec(party.etc[1]);
                 Silent_Scroll;
              end;
              if y = 18 then party.etc[1] := 1;
              if (y = 48) and (party.etc[41] and bit4 = 0) then begin
                 if party.etc[1] = 0 then begin
                    party.etc[1] := 1;
                    scroll(true);
                 end;
                 Print(11,'미로속에서 소를 닮은 괴물이 나타났다');
                 for i := 1 to 4 do begin
                    if i > 1 then putimage(100,(i-1)*20,font^[map[x,y-(6-i)]],copyput);
                    putimage(100,i*20,chara^[37],andput);
                    putimage(100,i*20,chara^[9],orput);
                    if i < 4 then delay(1000);
                 end;
                 PressAnyKey;
                 enemynumber := 1;
                 joinenemy(1,53);
                 Displayenemies(TRUE);
                 BattleMode(FALSE);
                 party.etc[41] := party.etc[41] or bit4;
              end;
              if y = 13 then begin
                 if party.etc[1] = 0 then begin
                    party.etc[1] := 1;
                    scroll(true);
                 end;
                 if party.etc[41] and bit2 = 0 then begin
                    for i := 4 to 6 do begin
                       for j := 0 to 1 do begin
                          putimage(20*i-j*80+40,20,chara^[4*(i-4)+39],andput);
                          putimage(20*i-j*80+40,20,chara^[4*(i-4)+11],orput);
                       end;
                    end;
                    delay(2000);
                    for j := 1 to 3 do begin
                       for i := 4 to 6 do
                       for k := 0 to 1 do begin
                          putimage(20*i-k*80+40,20*(j+1),font^[44],copyput);
                          putimage(20*i-k*80+40,20*(j+1),chara^[4*(i-4)+39],andput);
                          putimage(20*i-k*80+40,20*(j+1),chara^[4*(i-4)+11],orput);
                       end;
                       for i := 4 to 6 do
                       for k := 0 to 1 do begin
                          putimage(20*i-k*80+40,20*j,font^[44],copyput);
                          putimage(20*i-k*80+40,20*j,chara^[4*(i-4)+38],andput);
                          putimage(20*i-k*80+40,20*j,chara^[4*(i-4)+10],orput);
                       end;
                       if j > 1 then
                       for i := 4 to 6 do
                       for k := 0 to 1 do
                          putimage(20*i-k*80+40,20*(j-1),font^[44],copyput);
                       if j < 3 then delay(2000);
                    end;
                    for i := 4 to 6 do begin
                       putimage(20*i,20,chara^[4*(i-4)+39],andput);
                       putimage(20*i,20,chara^[4*(i-4)+11],orput);
                    end;
                    delay(1000);
                    for i := 4 to 6 do begin
                       putimage(20*i,40,font^[44],copyput);
                       putimage(20*i,40,chara^[4*(i-4)+39],andput);
                       putimage(20*i,40,chara^[4*(i-4)+11],orput);
                    end;
                    for i := 4 to 6 do begin
                       putimage(20*i,20,font^[44],copyput);
                       putimage(20*i,20,chara^[4*(i-4)+38],andput);
                       putimage(20*i,20,chara^[4*(i-4)+10],orput);
                    end;
                    delay(1000);
                    for i := 4 to 6 do begin
                       putimage(20*i,20,font^[44],copyput);
                       putimage(20*i,60,font^[44],copyput);
                       putimage(20*i,60,chara^[4*(i-4)+39],andput);
                       putimage(20*i,60,chara^[4*(i-4)+11],orput);
                    end;
                    putimage(80,60,chara^[46],andput);
                    putimage(80,60,chara^[18],orput);
                    putimage(120,60,chara^[38],andput);
                    putimage(120,60,chara^[10],orput);
                    for i := 4 to 6 do begin
                       putimage(20*i,40,font^[44],copyput);
                       putimage(20*i,40,chara^[4*(i-4)+38],andput);
                       putimage(20*i,40,chara^[4*(i-4)+10],orput);
                    end;
                    PressAnyKey;
                    enemynumber := 3;
                    for i := 1 to enemynumber do joinenemy(i,54);
                    Displayenemies(TRUE);
                    BattleMode(FALSE);
                    if party.etc[6] = 255 then exit;
                    if party.etc[6] = 0 then party.etc[41] := party.etc[41] or bit2
                    else begin
                       inc(y); scroll(TRUE);
                       exit;
                    end;
                 end;
                 if party.etc[41] and bit3 = 0 then begin
                    Clear;
                    enemynumber := 7;
                    for i := 1 to enemynumber do joinenemy(i,31);
                    DisplayEnemies(TRUE);
                    BattleMode(FALSE);
                    if party.etc[6] = 255 then exit;
                    if party.etc[6] = 0 then party.etc[41] := party.etc[41] or bit3
                    else begin
                       inc(y); scroll(TRUE);
                       exit;
                    end;
                 end;
                 if party.etc[41] and bit1 = 0 then begin
                    Clear;
                    Silent_Scroll;
                    for i := 1 to 4 do begin
                       putimage(20*i,20*i,chara^[13],copyput);
                       putimage(20*(i+1),20*i,chara^[41],copyput);
                       if i > 1 then begin
                          putimage(20*(i-1),20*(i-1),font^[44],copyput);
                          putimage(20*i,20*(i-1),font^[44],copyput);
                       end;
                       if i < 4 then delay(1500);
                    end;
                    Print(13,' 나는 Necromacer 와 함께 다른 차원에서 내려');
                    Print(13,'온 Astral Mud 이다. 여기는 그가 세운 최고의');
                    Print(13,'동굴이자 너가 마지막으로 거칠 동굴이다.  나');
                    Print(13,'를 만만하게 보지마라.  다른 차원의 능력들을');
                    Print(13,'너가 맛볼 기회를 가진다는 것에 대해  고맙게');
                    Print(13,'생각하기 바란다. 하하하 ...');
                    PressAnyKey;
                    enemynumber := 7;
                    for i := 1 to 6 do joinenemy(i,31);
                    joinenemy(7,57);
                    displayenemies(TRUE);
                    battlemode(FALSE);
                    if enemy[7].dead then begin
                       party.etc[41] := party.etc[41] or bit1;
                       Clear;
                       Print(15,' 당신은 이 동굴에 보관되어 있는 봉인을 발견');
                       Print(15,'했다.  그리고는 봉쇄 되었던 봉인을 풀어버렸');
                       Print(15,'다.');
                       with party do begin
                          xaxis := 82; yaxis := 17; map := 4;
                       end;
                       load;
                       PressAnyKey;
                       scroll(TRUE);
                       exit;
                    end
                    else begin
                       inc(y); scroll(TRUE);
                       exit;
                    end;
                 end
                 else begin
                    with party do begin
                       xaxis := 82; yaxis := 17; map := 4;
                    end;
                    load; scroll(TRUE);
                 end;
              end;
           end
